// StitchDB local Edge Functions router (generated by the stitchdb CLI; behaves like the production router).
// /<function>/... -> stitchdb/functions/<function>/index.ts in its own isolate, with the local project's env and
// the secrets from stitchdb/functions/.env. Code is re-read on every request, so edits apply immediately.

const JWT_SECRET = Deno.env.get('JWT_SECRET') ?? '';
const SLUG_RE = /^[A-Za-z0-9][A-Za-z0-9_-]{0,62}$/;
const enc = new TextEncoder();
const dec = new TextDecoder();

let settings: Record<string, { verify_jwt?: boolean }> = {};
try { settings = JSON.parse(await Deno.readTextFile('/home/deno/main/functions.json')); } catch { /* defaults */ }

function b64url(s: string): Uint8Array {
  s = s.replace(/-/g, '+').replace(/_/g, '/');
  while (s.length % 4) s += '=';
  return Uint8Array.from(atob(s), (c) => c.charCodeAt(0));
}
let key: CryptoKey | null = null;
async function verifyJwt(token: string): Promise<string | null> {
  const parts = token.split('.');
  if (parts.length !== 3) return 'Invalid JWT format';
  let header: { alg?: string }, payload: { exp?: number };
  try { header = JSON.parse(dec.decode(b64url(parts[0]))); payload = JSON.parse(dec.decode(b64url(parts[1]))); } catch { return 'Invalid JWT format'; }
  if (header.alg !== 'HS256') return `Unsupported JWT algorithm ${header.alg}`;
  key ??= await crypto.subtle.importKey('raw', enc.encode(JWT_SECRET), { name: 'HMAC', hash: 'SHA-256' }, false, ['verify']);
  const ok = await crypto.subtle.verify('HMAC', key, b64url(parts[2]), enc.encode(`${parts[0]}.${parts[1]}`)).catch(() => false);
  if (!ok) return 'Invalid JWT';
  if (typeof payload.exp === 'number' && payload.exp * 1000 < Date.now()) return 'JWT expired';
  return null;
}
const json = (status: number, code: string, message: string) => Response.json({ code, message, msg: message }, { status, headers: { 'x-stitchdb-error': code } });

// Env for function code: the project's URL/keys/database URL + secrets; never the router's own JWT secret.
const env = Object.entries(Deno.env.toObject()).filter(([k]) => k !== 'JWT_SECRET' && !k.startsWith('DENO_'));

Deno.serve(async (req: Request) => {
  const url = new URL(req.url);
  const [, slug = '', ...rest] = url.pathname.split('/');
  if (!SLUG_RE.test(slug) || slug === 'main') return json(404, 'NOT_FOUND', 'Requested function was not found');
  const dir = `/home/deno/functions/${slug}`;
  try { await Deno.stat(`${dir}/index.ts`); } catch { return json(404, 'NOT_FOUND', `Function "${slug}" was not found in stitchdb/functions/${slug}/index.ts`); }
  if (settings[slug]?.verify_jwt !== false && req.method !== 'OPTIONS') {
    const m = /^bearer\s+(\S+)$/i.exec((req.headers.get('authorization') ?? '').trim());
    const token = m ? m[1] : (req.headers.get('apikey') ?? '');
    if (!token) return json(401, 'UNAUTHORIZED_NO_AUTH_HEADER', 'Missing authorization header');
    const bad = await verifyJwt(token);
    if (bad) return json(401, 'UNAUTHORIZED_INVALID_JWT', bad);
  }
  let importMapPath: string | undefined;
  for (const f of ['deno.json', 'deno.jsonc', 'import_map.json']) { try { await Deno.stat(`${dir}/${f}`); importMapPath = `${dir}/${f}`; break; } catch { /* none */ } }
  try {
    const worker = await (globalThis as any).EdgeRuntime.userWorkers.create({
      servicePath: dir, memoryLimitMb: 256, workerTimeoutMs: 150_000, noModuleCache: true, forceCreate: true, importMapPath,
      envVars: [...env, ['STITCHDB_FUNCTION_SLUG', slug]],
    });
    const target = `http://localhost/${slug}${rest.length ? '/' + rest.join('/') : ''}${url.search}`;
    const userReq = new Request(target, { method: req.method, headers: req.headers, body: req.body, redirect: 'manual', duplex: 'half' } as RequestInit);
    (globalThis as any).EdgeRuntime.applySupabaseTag(req, userReq); // the runtime tracks the original request's stream
    return await worker.fetch(userReq);
  } catch (e) {
    console.error(`${slug}:`, String(e));
    const E = (Deno as any).errors;
    if (E?.InvalidWorkerCreation && e instanceof E.InvalidWorkerCreation) return json(503, 'BOOT_ERROR', `Function failed to start: ${String(e)}`);
    return json(500, 'WORKER_ERROR', 'Function exited with an error (see "stitchdb functions serve" output)');
  }
});
